package com.lookup.app

/** Backgrounds for the quote card. Generated by tools/make_scenes.py. */
object Scenes {
    private val ALL = listOf(
        R.drawable.scene_alpine_dawn,
        R.drawable.scene_aurora,
        R.drawable.scene_desert_dunes,
        R.drawable.scene_misty_forest,
        R.drawable.scene_ocean_sunset,
        R.drawable.scene_rolling_hills,
        R.drawable.scene_starry_lake,
    )

    private var last = -1

    /** A random scene, never the same one twice in a row. */
    fun random(): Int {
        var i: Int
        do { i = ALL.indices.random() } while (i == last)
        last = i
        return ALL[i]
    }
}
